import * as React from "react";

export type NavUpCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function NavUpCircleIcon({ size = 20, ...props }: NavUpCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5" /><path d="M8.5 14 12 10.5 15.5 14" />
    </svg>
  );
}
